// One item per route: the cheapest departure day in the window, compared with the previous run (workflow static data).
const MAX_KEYS = 5000;                       // routes remembered between runs (oldest dropped)
const store = $getWorkflowStaticData('global');
store.cheapest = store.cheapest || {};
const today = new Date().toISOString().slice(0, 10);
const rows = $input.all().map(i => i.json);
const fares = rows.filter(r => r.type === 'fare' && r.price != null);   // one row per route and day: that day's cheapest itinerary
const byRoute = {};
for (const f of fares) (byRoute[f.route] = byRoute[f.route] || []).push(f);
const out = [];
for (const [route, list] of Object.entries(byRoute)) {
  list.sort((a, b) => a.price - b.price || String(a.depart_date).localeCompare(String(b.depart_date)));
  const f = list[0];
  const st = rows.find(r => r.type === 'status' && r.route === route);
  const days = (st && st.days_searched) || list.length;
  const prev = store.cheapest[route];
  const change_pct = prev && prev.price ? Math.round((f.price - prev.price) / prev.price * 1000) / 10 : null;
  const change = change_pct == null ? 'first run, nothing to compare yet' : change_pct === 0 ? `unchanged (${prev.price} on ${prev.depart_date})` : `${change_pct > 0 ? '+' : ''}${change_pct}% (was ${prev.price} on ${prev.depart_date})`;
  const top3 = list.slice(0, 3).map(d => ({ depart_date: d.depart_date, price: d.price, airline: d.airline || null }));
  const message = [
    `✈️ ${route} — next ${days} days`,
    `Cheapest: ${f.price_display || f.price + ' ' + (f.currency || '')} on ${f.depart_date} (${f.airline || 'n/a'}, ${f.stops ?? '?'} stops, dep ${f.depart_time || 'n/a'})`,
    `vs yesterday: ${change}`,
    `Also: ${top3.map(d => `${d.depart_date} ${d.price}`).join(' · ')}`,
    f.google_url || '',
  ].join('\n');
  out.push({ json: { route, depart_date: f.depart_date, return_date: f.return_date || null, price: f.price, price_display: f.price_display || null, currency: f.currency || null,
    airline: f.airline || null, stops: f.stops ?? null, depart_time: f.depart_time || null, duration: f.duration || null, duration_minutes: f.duration_minutes ?? null, google_url: f.google_url || null,
    previous_price: prev ? prev.price : null, previous_date: prev ? prev.depart_date : null, change_pct, drop_pct: change_pct == null ? 0 : -change_pct,
    top3, days_priced: list.length, days_searched: days, message } });
  store.cheapest[route] = { price: f.price, depart_date: f.depart_date, run_date: today };
}
const keys = Object.keys(store.cheapest);
if (keys.length > MAX_KEYS) for (const k of keys.slice(0, keys.length - MAX_KEYS)) delete store.cheapest[k];
return out;
